class Solution {
    public int minimumKeypresses(String s) {
        Integer[] cnt = new Integer[26];
        Arrays.fill(cnt, 0);
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        Arrays.sort(cnt, Collections.reverseOrder());
        int ans = 0;
        for (int i = 0; i < 26; i++) ans += cnt[i] * (i / 9 + 1);
        return ans;
    }
}
